// Adapter: the rule below is the same JavaScript as the recipe's n8n build.
// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Config": "in0_Config", "Step 2: Read tomorrow's jobs": "in1_Step2Readtomorrowsjobs"};
const LISTS = [];
const EXECUTED = ["Step 2: Each afternoon"];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Step 2: Read tomorrow's jobs";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
const BODIES = (out) => ({"message_body": JSON.stringify(out.message), "nd_body": JSON.stringify({ id: 'ND-' + out.job + '-reminder', to: $('Config').first().json.dispatch_queue, job: out.job, type: 'message not delivered', reason: 'Reminder not delivered: send error. Phone the customer.' })});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
// Step 2: one reminder for each of tomorrow's jobs.
const cfg = $('Config').first().json;
const fill = (tpl, vals) => String(tpl).replace(/\{(\w+)\}/g, (m, k) => (k in vals ? String(vals[k]) : m));
return ($('Step 2: Read tomorrow\'s jobs').first().json.items || []).map(job => {
  const c = job.customer || {};
  return { json: { job: job.id, message: { id: 'R-' + job.id + '-' + job.slot_date, to: c.channel === 'email' ? c.email : c.phone, channel: c.channel,
    job: job.id, template: 'reminder', text: fill(cfg.reminder_template, { date: job.slot_date, window: job.window }) } } };
});
};
return { items: one(__rule()).map(o => Object.assign({}, o, BODIES(o))) };
